using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

// Stage-C same-trace visual replay. Physics remains authoritative in the Stage-B
// receipt; transform assignment here is rendering-only and never fed back.
public static class WeightedBimanualBaselineBuilder
{
    static readonly string Output=Environment.GetEnvironmentVariable("WEIGHTED_BASELINE_OUTPUT");
    static readonly string TracePath=Environment.GetEnvironmentVariable("WEIGHTED_BASELINE_TRACE");
    static GameObject avatar;static SkinnedMeshRenderer skin;static Camera camera;static Transform head;
    static readonly Dictionary<string,Transform> bones=new();static readonly Dictionary<Transform,Quaternion> rest=new();
    static readonly Vector3 Offset=new(0,.567f,-.35f);
    static GameObject toy,blueCup;static readonly List<Projection> projections=new();static int contextualObjects;
    static int maxHeroPixels;

    [MenuItem("BabyWorld/Run Weighted Bimanual Baseline")]
    public static void Run(){if(string.IsNullOrWhiteSpace(Output)||string.IsNullOrWhiteSpace(TracePath))throw new Exception("output and trace required");Directory.CreateDirectory(Output);Directory.CreateDirectory(Path.Combine(Output,"head_frames"));Directory.CreateDirectory(Path.Combine(Output,"external_frames"));
        var trace=JsonUtility.FromJson<Trace>(File.ReadAllText(TracePath));Build();var external=ExternalCamera();int visibleEvents=0;
        for(int frame=0;frame<trace.rows.Length;frame++){var row=trace.rows[frame];Pose(row);toy.transform.SetPositionAndRotation(row.object_position_m+Offset,row.object_rotation);if(blueCup)blueCup.transform.SetPositionAndRotation(row.blue_object_position_m+Offset,row.blue_object_rotation);Physics.SyncTransforms();
            if(row.measured_contact_count>0){Vector3 vp=camera.WorldToViewportPoint(row.object_position_m+Offset);if(vp.z>0&&vp.x>=0&&vp.x<=1&&vp.y>=0&&vp.y<=1)visibleEvents++;projections.Add(new Projection{frame=frame,time_s=row.time_s,contact_count=row.measured_contact_count,object_viewport=vp,visible=vp.z>0&&vp.x>=0&&vp.x<=1&&vp.y>=0&&vp.y<=1});}
            maxHeroPixels=Mathf.Max(maxHeroPixels,Capture(camera,Path.Combine(Output,"head_frames",$"frame_{frame:D4}.png")));Capture(external,Path.Combine(Output,"external_frames",$"frame_{frame:D4}.png"));}
        var rendererCount=avatar.GetComponentsInChildren<SkinnedMeshRenderer>(true).Count(x=>x.enabled);var report=new Report{schema="embodied.weighted_bimanual_baseline.v1",unity_version=Application.unityVersion,source_fbx_sha256=Sha256("Assets/Avatar/child.fbx"),source_license="CC0",duration_s=(trace.rows.Length-1)/30f,frames=trace.rows.Length,
            one_weighted_visible_child=rendererCount==1,both_arms_registered=ArmComplete("R")&&ArmComplete("L"),proxy_renderers_visible=0,camera_parent_bone=head.name,camera_body_derived=true,fov_deg=camera.fieldOfView,near_clip_m=camera.nearClipPlane,
            rendering_only_object_pose_assignments=trace.rows.Length*(blueCup?2:1),authoritative_physics_trace=TracePath,contact_projection_rows=projections.Count,contact_event_frames_visible=visibleEvents,hero_nonbackground_pixels_max=maxHeroPixels,contextual_object_count=contextualObjects};
        bool durationPass=trace.rows.Length>1000?report.duration_s>=45&&report.duration_s<=60:report.duration_s>=8&&report.duration_s<=12;report.passed=durationPass&&report.one_weighted_visible_child&&report.both_arms_registered&&report.proxy_renderers_visible==0&&report.camera_body_derived&&visibleEvents>0&&maxHeroPixels>10000&&(trace.rows.Length<=1000||contextualObjects>=6);
        File.WriteAllText(Path.Combine(Output,"contact_projections.json"),JsonUtility.ToJson(new ProjectionTrace{rows=projections.ToArray()},true));File.WriteAllText(Path.Combine(Output,"report.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(report.passed?0:2);}

    static void Build(){avatar=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Avatar/child.fbx"));avatar.name="CC0_WEIGHTED_CHILD";avatar.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);avatar.transform.localScale=Vector3.one*1.9f;skin=avatar.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();skin.enabled=true;skin.updateWhenOffscreen=true;var mat=new Material(Shader.Find("Standard"));mat.color=new Color(.72f,.45f,.32f);mat.SetFloat("_Glossiness",.2f);skin.sharedMaterial=mat;
        foreach(var t in avatar.GetComponentsInChildren<Transform>(true)){bones[t.name]=t;rest[t]=t.localRotation;}head=bones["head"];
        Bounds hb=HeadBounds();Vector3 cameraWorld=new(hb.center.x,hb.center.y+.018f,hb.min.z-.032f);var camGo=new GameObject("fixed_child_head_camera");camGo.transform.SetPositionAndRotation(cameraWorld,Quaternion.LookRotation(new Vector3(0,-Mathf.Sin(50*Mathf.Deg2Rad),-Mathf.Cos(50*Mathf.Deg2Rad)),Vector3.up));camGo.transform.SetParent(head,true);camera=camGo.AddComponent<Camera>();camera.fieldOfView=68;camera.nearClipPlane=.03f;camera.farClipPlane=10;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.35f,.42f,.48f);
        var support=Cube("low_play_table",new Vector3(0,.5795f,-.35f),new Vector3(.92f,.025f,.68f),new Color(.62f,.43f,.24f));toy=Cube("red_toy_replay",new Vector3(0,.62f,-.35f),Vector3.one*.055f,new Color(.85f,.035f,.025f));UnityEngine.Object.DestroyImmediate(toy.GetComponent<Collider>());blueCup=Cube("blue_cup_replay",new Vector3(.14f,.63f,-.40f),new Vector3(.06f,.075f,.06f),new Color(.04f,.18f,.85f));UnityEngine.Object.DestroyImmediate(blueCup.GetComponent<Collider>());
        Cube("shallow_bin",new Vector3(-.09f,.607f,-.27f),new Vector3(.22f,.03f,.18f),new Color(.24f,.58f,.34f));Cube("picture_book",new Vector3(.20f,.606f,-.25f),new Vector3(.18f,.012f,.14f),new Color(.92f,.64f,.12f));Cube("stacking_ring",new Vector3(-.27f,.625f,-.43f),new Vector3(.07f,.07f,.07f),new Color(.75f,.18f,.55f));Cube("wooden_train",new Vector3(.31f,.625f,-.48f),new Vector3(.12f,.06f,.07f),new Color(.18f,.62f,.72f));contextualObjects+=6;
        Cube("floor",new Vector3(0,-.035f,-1.8f),new Vector3(4.8f,.07f,5.4f),new Color(.43f,.29f,.18f));Cube("warm_wall",new Vector3(0,1.35f,-4.45f),new Vector3(4.8f,2.7f,.08f),new Color(.74f,.79f,.75f));Cube("window",new Vector3(1.1f,1.45f,-4.40f),new Vector3(1.1f,.9f,.03f),new Color(.55f,.76f,.93f));
        PlaceAsset("rugRectangle",new Vector3(.1f,0,-1.9f),2.35f,0);PlaceAsset("loungeSofaLong",new Vector3(1.05f,0,-3.72f),2.05f,0);PlaceAsset("bookcaseOpen",new Vector3(-1.82f,0,-3.68f),1.75f,0);PlaceAsset("pottedPlant",new Vector3(-1.68f,0,-2.62f),1.05f,180);PlaceAsset("lampSquareFloor",new Vector3(1.9f,0,-3.42f),1.65f,180);contextualObjects+=5;
        var light=new GameObject("warm_key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.4f;light.transform.rotation=Quaternion.Euler(48,-28,0);RenderSettings.ambientLight=new Color(.32f,.30f,.28f);}
    static void Pose(TraceRow row){foreach(var kv in rest)if(kv.Key)kv.Key.localRotation=kv.Value;Vector3 right=row.right_palm_position_m+Offset,left=row.left_palm_position_m+Offset;Solve("R",right);Solve("L",left);Curl("R",row.right_closure);Curl("L",row.left_closure);
        float scan=row.time_s<6?Mathf.Sin(row.time_s*.8f):row.time_s>=39&&row.time_s<48?Mathf.Sin((row.time_s-39)*.35f):row.time_s>=48?1:0;head.localRotation=rest[head]*Quaternion.Euler(4+3*scan,9*scan,-1.5f*scan);}
    static void Solve(string side,Vector3 target){string[] chain={"upperarm01."+side,"upperarm02."+side,"lowerarm01."+side,"lowerarm02."+side,"wrist."+side};Transform wrist=bones["wrist."+side];for(int pass=0;pass<16;pass++)for(int i=chain.Length-1;i>=0;i--){var b=bones[chain[i]];Vector3 a=wrist.position-b.position,c=target-b.position;if(a.sqrMagnitude>1e-8f&&c.sqrMagnitude>1e-8f)b.rotation=Quaternion.Slerp(Quaternion.identity,Quaternion.FromToRotation(a,c),.48f)*b.rotation;}}
    static void Curl(string side,float amount){for(int d=1;d<=5;d++)for(int p=1;p<=3;p++){var f=bones[$"finger{d}-{p}.{side}"];f.localRotation=rest[f]*Quaternion.Euler((p==1?28:42)*amount*(side=="R"?1:-1),0,0);}}
    static bool ArmComplete(string s){string[] names={"upperarm01.","upperarm02.","lowerarm01.","lowerarm02.","wrist.","finger1-1.","finger2-1.","finger3-1.","finger4-1.","finger5-1."};return names.All(n=>bones.ContainsKey(n+s));}
    static Camera ExternalCamera(){var c=new GameObject("clean_external_camera").AddComponent<Camera>();c.transform.position=new Vector3(.85f,1.05f,.55f);c.transform.LookAt(new Vector3(0,.7f,-.3f));c.fieldOfView=44;c.backgroundColor=new Color(.25f,.3f,.34f);return c;}
    static GameObject Cube(string n,Vector3 p,Vector3 s,Color color){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;var m=new Material(Shader.Find("Standard"));m.color=color;g.GetComponent<Renderer>().sharedMaterial=m;return g;}
    static GameObject PlaceAsset(string name,Vector3 position,float maxDimension,float yaw){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>($"Assets/Furniture/{name}.obj");if(!prefab)return null;var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.name=name;g.transform.rotation=Quaternion.Euler(0,yaw,0);var bounds=g.GetComponentsInChildren<Renderer>().Select(x=>x.bounds).Aggregate((a,b)=>{a.Encapsulate(b);return a;});g.transform.localScale=Vector3.one*(maxDimension/Mathf.Max(bounds.size.x,Mathf.Max(bounds.size.y,bounds.size.z)));bounds=g.GetComponentsInChildren<Renderer>().Select(x=>x.bounds).Aggregate((a,b)=>{a.Encapsulate(b);return a;});g.transform.position=position+Vector3.up*(-bounds.min.y);return g;}
    static Bounds HeadBounds(){var mesh=skin.sharedMesh;var weights=mesh.boneWeights;int index=Array.IndexOf(skin.bones,head);var points=new List<Vector3>();for(int i=0;i<weights.Length;i++){var w=weights[i];float v=0;if(w.boneIndex0==index)v+=w.weight0;if(w.boneIndex1==index)v+=w.weight1;if(w.boneIndex2==index)v+=w.weight2;if(w.boneIndex3==index)v+=w.weight3;if(v>=.25f)points.Add(skin.transform.TransformPoint(mesh.vertices[i]));}var b=new Bounds(points[0],Vector3.zero);foreach(var p in points)b.Encapsulate(p);return b;}
    static int Capture(Camera c,string path){var rt=new RenderTexture(960,540,24);var tex=new Texture2D(960,540,TextureFormat.RGB24,false);c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,960,540),0,0);tex.Apply();Color32 bg=c.backgroundColor;int nonbg=0;foreach(var p in tex.GetPixels32())if(Mathf.Abs(p.r-bg.r)>3||Mathf.Abs(p.g-bg.g)>3||Mathf.Abs(p.b-bg.b)>3)nonbg++;File.WriteAllBytes(path,tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);return nonbg;}
    static string Sha256(string path){using var h=System.Security.Cryptography.SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
    [Serializable]class Trace{public TraceRow[] rows;}[Serializable]class TraceRow{public float time_s;public string phase;public Vector3 object_position_m,blue_object_position_m,right_palm_position_m,left_palm_position_m;public Quaternion object_rotation,blue_object_rotation;public float right_closure,left_closure;public int measured_contact_count;}
    [Serializable]class ProjectionTrace{public Projection[] rows;}[Serializable]class Projection{public int frame,contact_count;public float time_s;public Vector3 object_viewport;public bool visible;}
    [Serializable]class Report{public string schema,unity_version,source_fbx_sha256,source_license,camera_parent_bone,authoritative_physics_trace;public float duration_s,fov_deg,near_clip_m;public int frames,proxy_renderers_visible,rendering_only_object_pose_assignments,contact_projection_rows,contact_event_frames_visible,hero_nonbackground_pixels_max,contextual_object_count;public bool one_weighted_visible_child,both_arms_registered,camera_body_derived,passed;}
}
